def icon(k):return '<span class="icon"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.4" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+icons[k]+'</svg></span>'
def url(p=''):return BASE+p.strip('/')+('/' if p else '')
def link(p,t,cls=''):return f'<a href="{url(p)}" class="{cls}">{t}</a>'
def btn(p,t,cls=''):return link(p,t+' <span class="arrow" aria-hidden="true">↗</span>','btn '+cls)
def eye(t):return '<div class="eyebrow">'+t+'</div>'
services=[('procurement','IT procurement','it-procurement','Smarter sourcing. Simpler procurement.','From a single specification to a bulk equipment enquiry, bring clarity to your next IT purchase.'),('hardware','Computer hardware','hardware','The right hardware for the job.','Explore business computers, servers, networking equipment and everyday essentials.'),('consulting','IT consulting','consulting','Practical advice. Clear direction.','Make informed technology decisions that fit your organization, priorities and budget.'),('support','Technical support','technical-support','Keep your technology moving.','Discuss setup, servicing and maintenance requirements with a team focused on your needs.')]
def servicecards():return '<div class="cards">'+''.join(f'<article class="card"><span class="num">0{i+1}</span>{icon(k)}<h3>{title}</h3><p>{desc}</p>{link("services/"+slug,"Explore service <span aria-hidden=\"true\">↗</span>","text-link")}</article>' for i,(k,title,slug,tag,desc) in enumerate(services))+'</div>'
